/// <summary>
/// CB 797 send PE pricing Data contract class for service <c>METSendPricingLineContract</c>
/// </summary>
[DataContractAttribute]
public class METSendPricingLineContract
{

    DataAreaId               dataAreaId;
    SalesId                  salesId;
    InventTransId            inventTransId;
    LineNum                  linenum;
    ItemId                   itemId;
    SalesQty                 salesQty;
    SalesUnit                salesUnit;
    SalesPrice               salesPrice;
    SalesLineDisc            lineDiscountAmount;
    METLineIndicator         lineIndicator;
    METAIS                   AIS;
    private List             priceComponentArray;
    private List             priceMarkupArray;



}

