/// <summary>
/// send PE pricing component
/// </summary>
/// <param name = "_metPriceComponentClassArray">PE pricing component</param>
/// <returns>returns PE pricing component</returns>
[DataMemberAttribute("METPriceComponentContract"),
DataCollection(Types::Class, classStr(METPriceComponentContract)),
AifCollectionTypeAttribute('_metPriceComponentClassArray', Types::Class, classStr(METPriceComponentContract)),
AifCollectionTypeAttribute('return', Types::Class, classStr(METPriceComponentContract))]
public List parmsendPEPriceComponetClassArray(List _metPriceComponentClassArray = priceComponentArray)
{
    if (!prmIsDefault(_metPriceComponentClassArray))
    {
        priceComponentArray = _metPriceComponentClassArray;
    }

    return priceComponentArray;
}

